SELECT [Станции(архив)].numb1120, [Станции(архив)].name, Типы_оборудования.gruppa_oborud, Списки_агрегатов.[2023], Списки_агрегатов.Year AS yearin, [Станции(архив)].Year, Списки_агрегатов.stnumb, [Станции_для_сводной(архив)].nov_Belyaev, [Станции_для_сводной(архив)].KPD_el, [Станции_для_сводной(архив)].KPD, [Станции_для_сводной(архив)].KIUM, [Станции_для_сводной(архив)].oblname, [Станции_для_сводной(архив)].BLST_V, [Станции_для_сводной(архив)].W, [Станции_для_сводной(архив)].B, [Станции_для_сводной(архив)].obor
FROM [Станции_для_сводной(архив)] INNER JOIN (([Станции(архив)] INNER JOIN Списки_агрегатов ON [Станции(архив)].numb1120 = Списки_агрегатов.grcode) INNER JOIN Типы_оборудования ON [Станции(архив)].obor = Типы_оборудования.code) ON ([Станции_для_сводной(архив)].Year = [Станции(архив)].year) AND ([Станции_для_сводной(архив)].numb1120 = [Станции(архив)].numb1120)
WHERE (((Списки_агрегатов.[2023])>0) AND ((Списки_агрегатов.Year)<2024) AND (([Станции(архив)].Year)=2023) AND (([Станции_для_сводной(архив)].KPD_el)<100) AND ((Списки_агрегатов.ur)=1) AND (([Станции_для_сводной(архив)].W)>0) AND (([Станции_для_сводной(архив)].B)>0))
ORDER BY [Станции(архив)].numb1, Списки_агрегатов.stnumb;
